{"file_path":"tests/test_spec.py","content":""""Examples and edge cases for each section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_pooled_by_transcript():
    groups = {"a": [event("a", 1, True)],
              "b": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_section_3_trailing_window():
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 9) == 6
    assert flags_in_window([], 1) == 0


def test_section_4_parse_fields_and_skipped_lines():
    assert parse_transcript_log(["  # comment\n", "\n", "  \t ",
                                 " a , 1 , 1 ", "b, -2, 0", "c,3, "]) == [
        event("a", 1, True), event("b", -2, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1"])
def test_section_4_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", " ", "a,1,1", bad_line])


def test_section_5_last_duplicate_wins_and_result_is_sorted():
    old = event("a", 1, True)
    new = event("a", 3, False)
    b = event("b", 2, True)
    c = event("c", 2, None)
    assert dedupe_transcripts([old, c, b, new]) == [b, c, new]
    assert dedupe_transcripts([]) == []


def test_section_6_counts_inclusive_range_and_missing_days():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_section_7_summary():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 3, False), event("c", 4, None)], "empty": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("a", 1, True)], "empty": [],
              "b": [event("b", 1, False)], "a": [event("c", 1, True)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 2) == []


def test_section_9_rates_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]
    assert flag_rate_by_group({}) == {}


def test_section_10_positive_consecutive_entries():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([1, 0, 1]) == 1
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
